sys_ui_action.script:
(function executeRule(current, previous) {
    try {
        var orchestrator = new x_snc_ai_sdlc.AIOrchestrator(current);
        var ids = orchestrator.createATFRecords();

        if (ids && ids.suiteId) {
            gs.addInfoMessage(
                'ATF records created successfully. ' +
                '<a href="/sys_atf_suite.do?sys_id=' + ids.suiteId + '" target="_blank">View ATF Suite</a>'
            );
        } else {
            gs.addInfoMessage('ATF records created. View the AI Manifest for details.');
        }
    } catch (e) {
        gs.addErrorMessage('ATF creation failed: ' + e.message + '. Check the Orchestration Log on the AI Manifest record.');
    }
    action.setRedirectURL(current);
})(current, previous);
